SELECT answer_id, notification_id, question_id, answer_data, user_id, user_type, student_user_id, create_time
FROM notification_answer
WHERE notification_id = #{notificationId}
AND student_user_id = #{userId}
ORDER BY question_id, answer_id

SELECT COUNT(*)
FROM notification_answer
WHERE notification_id = #{notificationId}
AND question_id = #{questionId}
AND student_user_id = #{studentUserId}
